-- Step 2: Insert new structured semantic EPSS chunks
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-08-first-epss-p1-1', 'doc-08-first-epss', 'doc-08-first-epss', 'Introduction', NULL, 'Exploit Prediction Scoring System (EPSS) The Exploit Prediction Scoring System (EPSS) is a data-driven machine-learning model that estimates the probability that a published CVE will be exploited in the wild in the next 30 days. It offsets subjective judgments with empirical signals from observed exploitation and ongoing activity, helping you focus limited remediation effort where attacks are most likely. EPSS publishes a 0–1 probability (with ranking percentiles) every day for every CVE and makes the data freely and openly accessible via CSV and API as well as a github repo , so it slots easily into workflows and dashboards.', 'vec_doc-08-first-epss-p1-1', 0, 159, 'v2.1.0', '3d738ffbac216fe096b583c5df979054ca64b65742311fe981bbf73e50f9dcc9', '{"document_id":"doc-08-first-epss","document_title":"FIRST EPSS v3 User Guide & Specification","chapter":"Specification","section":"Introduction","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"VULNERABILITY","authority_tier":0,"chunk_seq":1,"source_path":".zayron/knowledge/physical-15/08-first-epss.html","section_path":"Specification > Introduction"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-08-first-epss-p1-2', 'doc-08-first-epss', 'doc-08-first-epss', 'Where to go from here', NULL, 'How It Works Model methodology, feature overview, calibration, and known limitations. Why EPSS? The empirical case for exploitation likelihood as a prioritization signal. Performance data, CVSS comparison, and what the research shows. Using EPSS How to set thresholds, combine EPSS with CVSS and KEV, interpret score changes, and avoid common misuses. Frequently Asked Questions Answers to the questions practitioners ask most often about the score, the percentile, and how EPSS compares to other tools. Research Peer-reviewed papers, presentations, and the version changelog. Get the Data API reference, daily CSV downloads, historical scores, and integration examples.', 'vec_doc-08-first-epss-p1-2', 0, 168, 'v2.1.0', 'ddc84d5f37ad4d18d109e58fc85f0d7a62f49dbc50cdaee5a64f5fc29abbffe1', '{"document_id":"doc-08-first-epss","document_title":"FIRST EPSS v3 User Guide & Specification","chapter":"Specification","section":"Where to go from here","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"VULNERABILITY","authority_tier":0,"chunk_seq":2,"source_path":".zayron/knowledge/physical-15/08-first-epss.html","section_path":"Specification > Where to go from here"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-08-first-epss-p1-3', 'doc-08-first-epss', 'doc-08-first-epss', 'Get involved', NULL, 'The EPSS Special Interest Group (SIG) is a practitioner community focused on putting EPSS to work. Members meet every other Friday, share implementations, and contribute case studies and talks. If you use EPSS or want to, the SIG is where the conversation happens.', 'vec_doc-08-first-epss-p1-3', 0, 66, 'v2.1.0', '0929c0278612f2310fa18f2d1e068a7e13816400b67804684c91ae2f219ee14d', '{"document_id":"doc-08-first-epss","document_title":"FIRST EPSS v3 User Guide & Specification","chapter":"Specification","section":"Get involved","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"VULNERABILITY","authority_tier":0,"chunk_seq":3,"source_path":".zayron/knowledge/physical-15/08-first-epss.html","section_path":"Specification > Get involved"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-08-first-epss-p1-4', 'doc-08-first-epss', 'doc-08-first-epss', 'Special Thanks', NULL, 'Special thank you to all of our data partners who make EPSS possible. Exploitation activity data used in EPSS is provided in part by a number of industry and government partners, which includes but is not limited to: VulnCheck KEV (VulnCheck Known Exploited Vulnerabilities), Shadow Server Foundation and LevelBlue . EPSS is maintained by the EPSS Special Interest Group at FIRST. Scores are generated by Empirical Security and published freely to the community. Exploit Prediction Scoring System (EPSS) Why EPSS? Get the Data Using EPSS How EPSS Works Frequently Asked Questions Research Who is using EPSS? Log4Shell Use Case', 'vec_doc-08-first-epss-p1-4', 0, 157, 'v2.1.0', '3955f0a3ef1bdabda45b029d195ea768e1a1100e293260777b60994b1703e964', '{"document_id":"doc-08-first-epss","document_title":"FIRST EPSS v3 User Guide & Specification","chapter":"Specification","section":"Special Thanks","subsection":"UNKNOWN","table_id":null,"page":null,"domain":"VULNERABILITY","authority_tier":0,"chunk_seq":4,"source_path":".zayron/knowledge/physical-15/08-first-epss.html","section_path":"Specification > Special Thanks"}');